1	/**
2	 * api.ts — Cloudflare Worker entry point
3	 *
4	 * This file is intentionally thin: it wires together the Hono app,
5	 * queue consumer, and cron handlers, then re-exports named Durable Object
6	 * and Workflow classes so Wrangler can register them.
7	 *
8	 * Routes skipped (use Node-only features):
9	 *   - pluginUiStaticRoutes    fs.readFileSync / res.sendFile
10	 *   - instanceDatabaseBackupRoutes  pg_dump
11	 *
12	 * Routes handled via CF-native modules (not in route-registry.ts):
13	 *   - adapterRoutes       → src/worker/routes/adapters.ts
14	 *   - pluginRoutes        → src/worker/routes/plugins.ts
15	 *   - companySkillRoutes  → src/worker/routes/company-skills-cf.ts
16	 *   - accessRoutes        → route-registry.ts (extractAllRoutesFromRouter)
17	 *
18	 * Architecture note on per-request DB injection:
19	 *   Route handlers capture a `db` reference via service factory closures.
20	 *   Because Hyperdrive connections cannot be reused across CF Workers requests,
21	 *   we rebuild the DB + route handlers on every request. Route path regexps
22	 *   are static and are cached at module level in route-registry.ts.
23	 */
24	
25	import { bootCloudflare } from "../boot.js";
26	import { app } from "./app.js";
27	import { createHyperdriveDb } from "../db/hyperdrive.js";
28	import { runHeartbeatSweep } from "../cron/heartbeat-sweep.js";
29	import type { Env } from "./env.js";
30	
31	// Re-export Env so other modules (e.g. heartbeat-sweep) can import it from here.
32	export type { Env };
33	
34	// ---------------------------------------------------------------------------
35	// Workers fetch handler
36	// ---------------------------------------------------------------------------
37	
38	export default {
39	  fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
40	    // Boot CF implementations (idempotent — safe to call on every request).
41	    bootCloudflare(env);
42	    return Promise.resolve(app.fetch(request, env, ctx));
43	  },
44	
45	  // -------------------------------------------------------------------------
46	  // Queues consumer
47	  // -------------------------------------------------------------------------
48	  async queue(batch: MessageBatch<unknown>, env: Env): Promise<void> {
49	    for (const message of batch.messages) {
50	      const body = message.body as Record<string, unknown>;
51	      const type = body?.type as string | undefined;
52	
53	      if (type === "plugin_job_dispatch") {
54	        const pluginJobId = body.pluginJobId as string;
55	        const pluginSlug = body.pluginSlug as string;
56	        const companyId = body.companyId as string;
57	        const executorMode = (body.executorMode as "sandbox_bridge" | "container") ?? "sandbox_bridge";
58	        try {
59	          await env.PLUGIN_DISPATCH_WORKFLOW.create({
60	            id: `plugin-job-${pluginJobId}`,
61	            params: { pluginJobId, pluginSlug, companyId, executorMode },
62	          });
63	          message.ack();
64	        } catch (err) {
65	          console.error(`[Queue] Failed to start PluginDispatchWorkflow for job ${pluginJobId}: ${err instanceof Error ? err.message : String(err)}`);
66	          message.retry();
67	        }
68	        continue;
69	      }
70	
71	      if (type === "heartbeat_dispatch") {
72	        const agentId = body.agentId as string;
73	        const companyId = body.companyId as string;
74	        const runId = body.runId as string;
75	        const taskId = body.taskId as string | undefined;
76	        try {
77	          await env.HEARTBEAT_WORKFLOW.create({
78	            id: `heartbeat-${runId}`,
79	            params: { agentId, companyId, runId, taskId },
80	          });
81	          message.ack();
82	        } catch (err) {
83	          console.error(`[Queue] Failed to start HeartbeatWorkflow for run ${runId}: ${err instanceof Error ? err.message : String(err)}`);
84	          message.retry();
85	        }
86	        continue;
87	      }
88	
89	      console.warn(`[Queue] Unknown message type: ${type ?? "(none)"}`);
90	      message.ack();
91	    }
92	  },
93	
94	  // -------------------------------------------------------------------------
95	  // Cron triggers
96	  // -------------------------------------------------------------------------
97	  async scheduled(event: ScheduledEvent, env: Env, _ctx: ExecutionContext): Promise<void> {
98	    if (event.cron === "*/5 * * * *") {
99	      const db = createHyperdriveDb(env.HYPERDRIVE);
100	      await runHeartbeatSweep(env, db);
101	      return;
102	    }
103	    // "0 * * * *"  — budget threshold check (not yet implemented)
104	    // "0 3 * * *"  — DB backup (not yet implemented)
105	  },
106	};
107	
108	// ---------------------------------------------------------------------------
109	// Named Durable Object + Workflow exports
110	// Wrangler requires these to be named exports from the Worker's main module.
111	// ---------------------------------------------------------------------------
112	
113	export { TaskDO } from "../runtime/task-do.js";
114	export { AgentRunDO } from "../runtime/agent-run-do.js";
115	export { SchedulerDO } from "../scheduler/scheduler-do.js";
116	export { HeartbeatWorkflow } from "../runtime/workflows/heartbeat.js";
117	export { PluginDispatchWorkflow } from "../runtime/workflows/plugin-dispatch.js";
118	export { SidecarContainer, PluginContainer } from "./containers.js";
